		sections := p.SectionsEntries()
		meta := p.m
		cfg := meta.pageConfig
		kind := cfg.Kind

		switch kind {
		case kinds.KindSection:
			if len(sections) > 0 {
				section = sections[0]
			}
		case kinds.KindTaxonomy, kinds.KindTerm:
			if meta.singular != "" {
